def calculate_utilization(task):
    return task.e / task.p

def calculate_density(task):
    return task.e / min(task.p, task.D)

def calculate_total_utilization(task_set):
    total_u = 0
    for task in task_set:
        total_u += calculate_utilization(task)
    return total_u

def calculate_total_density(task_set):
    total_delta = 0
    for task in task_set:
        total_delta += calculate_density(task)
    return total_delta

