    remaining_exec = calculate_local_remaining_execution(task_i, current_time, slice_end_time, work_done_in_slice)
    time_remaining_in_slice = slice_end_time - current_time
    if time_remaining_in_slice == 0: return float('inf') # Avoid division by zero
    return remaining_exec / time_remaining_in_slice

